import java.io.*

fun main() {
    val input = System.stdin.readText().trim().split("\n").map { it.trim() }.filter { it.isNotEmpty() }
    var lineIndex = 0

    fun nextLine(): String {
        val line = input[lineIndex]
        lineIndex++
        return line
    }

    fun nextInts(): List<Int> = nextLine().split("\\s+".toRegex()).map { it.toInt() }

    val nk = nextInts()
    val n = nk[0]
    val a = nextInts()

    val r = IntArray(n)

    for (i in a) {
        for (j in i - 1 until n) {
            if (r[j] == 0) {
                r[j] = i
            } else {
                break
            }
        }
    }

    println(r.joinToString(" "))
}

