    val k = it.next().toInt()
    val a = IntArray(k) { it.next().toInt() }

    val r = IntArray(n) { 0 }

    for (i in a) {
        for (j in i - 1 until n) {
            if (r[j] == 0) {
                r[j] = i
            } else {
                break
            }
        }
    }

    println(r.joinToString(" "))
}

